@router.post("/predict", status_code=status.HTTP_200_OK, response_model=PredictionResponse)
async def predict(dto: AdvModel) -> PredictionResponse:
    result = advertisement_service.predict(dto)
    return PredictionResponse(resp=result)

@dataclass(frozen=True)
class AdvertisementService:
    def predict(self, adv: AdvModel) -> bool: 
        if adv.is_verified_seller:
            return True
        if adv.images_qty > 0:
            return True
        return False

def test_predict_validation(app_client: TestClient, invalid_data: dict):
    response = app_client.post("/advertisement/predict", json=invalid_data)
    assert response.status_code == HTTPStatus.UNPROCESSABLE_ENTITY

def test_predict_internal_error(app_client: TestClient):
    response = app_client.post("/advertisement/predict", json={})
    assert response.status_code == HTTPStatus.UNPROCESSABLE_ENTITY
